import 'package:flutter/material.dart';
import 'editorial_api.dart';
import 'studio_widgets.dart';

class TeamPage extends StatefulWidget{final EditorialApi api;const TeamPage({super.key,required this.api});@override State<TeamPage> createState()=>_TeamPageState();}
class _TeamPageState extends State<TeamPage>{late Future<List<dynamic>> future;@override void initState(){super.initState();future=widget.api.members();}void reload()=>setState(()=>future=widget.api.members());
 @override Widget build(BuildContext c)=>FutureBuilder<List<dynamic>>(future:future,builder:(c,s){if(s.connectionState!=ConnectionState.done)return const Center(child:CircularProgressIndicator());if(s.hasError)return StudioErrorState(onRetry:reload,message:'Cette vue est réservée au propriétaire EduNova.');final rows=s.data!;return ListView(padding:const EdgeInsets.all(24),children:[Row(children:[Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('Équipe éditoriale',style:Theme.of(c).textTheme.headlineSmall?.copyWith(fontWeight:FontWeight.w800)),const SizedBox(height:4),Text('Rôles internes EduNova uniquement. Aucun rôle n’est lié à une université.',style:Theme.of(c).textTheme.bodyMedium)])),FilledButton.icon(onPressed:()=>_edit(c,null),icon:const Icon(Icons.person_add_alt_1),label:const Text('Ajouter'))]),const SizedBox(height:18),StudioSection(title:'Membres',subtitle:'Principe du moindre privilège : chaque personne reçoit uniquement le rôle nécessaire.',child:rows.isEmpty?const Text('Aucun membre'):Column(children:[for(final m in rows)_MemberTile(member:m as Map<String,dynamic>,onEdit:()=>_edit(c,m))]))]);});
 Future<void> _edit(BuildContext c,Map<String,dynamic>? member)async{final r=await showDialog<Map<String,dynamic>>(context:c,builder:(_)=>_MemberDialog(member:member));if(r==null)return;try{await widget.api.setMember(r);if(mounted){ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Membre mis à jour.')));reload();}}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('Modification impossible : $e')));}}
}
class _MemberTile extends StatelessWidget{final Map<String,dynamic> member;final VoidCallback onEdit;const _MemberTile({required this.member,required this.onEdit});@override Widget build(BuildContext c){final active=member['active']==true;return ListTile(contentPadding:const EdgeInsets.symmetric(vertical:6),leading:CircleAvatar(child:Text(((member['role']?.toString().isNotEmpty??false)?member['role'].toString().substring(0,1):'?').toUpperCase())),title:Text(member['account_id']??'',style:const TextStyle(fontWeight:FontWeight.w700)),subtitle:Text(member['role']??''),trailing:Row(mainAxisSize:MainAxisSize.min,children:[StatusPill(active?'Actif':'Désactivé',color:active?Colors.green:Colors.grey),IconButton(onPressed:onEdit,tooltip:'Modifier',icon:const Icon(Icons.edit_outlined))]));}}
class _MemberDialog extends StatefulWidget{final Map<String,dynamic>? member;const _MemberDialog({this.member});@override State<_MemberDialog> createState()=>_MemberDialogState();}
class _MemberDialogState extends State<_MemberDialog>{late final TextEditingController id;late String role;late bool active;@override void initState(){super.initState();id=TextEditingController(text:widget.member?['account_id']??'');role=widget.member?['role']??'editor';active=widget.member?['active']??true;}@override Widget build(BuildContext c)=>AlertDialog(title:Text(widget.member==null?'Ajouter un membre':'Modifier le membre'),content:SizedBox(width:500,child:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:id,enabled:widget.member==null,decoration:const InputDecoration(labelText:'ID du compte EduNova')),const SizedBox(height:12),DropdownButtonFormField(value:role,decoration:const InputDecoration(labelText:'Rôle'),items:const[DropdownMenuItem(value:'owner',child:Text('Owner — administration complète')),DropdownMenuItem(value:'editor',child:Text('Editor — contenu et révisions')),DropdownMenuItem(value:'reviewer',child:Text('Reviewer — contrôle qualité')),DropdownMenuItem(value:'publisher',child:Text('Publisher — publication'))],onChanged:(v)=>setState(()=>role=v!)),SwitchListTile(contentPadding:EdgeInsets.zero,title:const Text('Compte actif dans le Studio'),value:active,onChanged:(v)=>setState(()=>active=v))])),actions:[TextButton(onPressed:()=>Navigator.pop(c),child:const Text('Annuler')),FilledButton(onPressed:id.text.trim().isEmpty?null:()=>Navigator.pop(c,{'account_id':id.text.trim(),'role':role,'active':active}),child:const Text('Enregistrer'))]);}
